package app.layan.test;
import android.app.*;import android.content.*;import android.os.*;import android.view.*;import android.graphics.*;import java.io.*;import app.layan.quran.*;import app.layan.quran.view.*;
public final class QiraatImmersiveRegression extends Instrumentation {
 public void onCreate(Bundle b){super.onCreate(b);start();}
 private View image(View v){if(v instanceof HighlightingImageView){Rect r=new Rect();if(v.getGlobalVisibleRect(r)&&r.width()>v.getWidth()/2)return v;}if(v instanceof ViewGroup)for(int i=0;i<((ViewGroup)v).getChildCount();i++){View f=image(((ViewGroup)v).getChildAt(i));if(f!=null)return f;}return null;}
 private void chrome(Activity a,boolean visible){boolean shown=a.findViewById(QiraatReaderActivity.HEADER).getVisibility()==View.VISIBLE;boolean hidden=(a.getWindow().getDecorView().getSystemUiVisibility()&View.SYSTEM_UI_FLAG_FULLSCREEN)!=0;if(shown!=visible||hidden==visible)throw new AssertionError("System bars and toolbar visibility disagree");if(Build.VERSION.SDK_INT>=30){WindowInsets insets=a.getWindow().getDecorView().getRootWindowInsets();if(insets!=null&&insets.isVisible(WindowInsets.Type.statusBars())!=visible)throw new AssertionError("Status bar visible despite fullscreen");}}
 public void onStart(){Bundle result=new Bundle();try{QiraatReaderActivity a=(QiraatReaderActivity)startActivitySync(new Intent(getTargetContext(),QiraatReaderActivity.class).putExtra("riwayah","warsh").putExtra("page",300).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));long end=SystemClock.elapsedRealtime()+120000;while(!a.currentPageReady()){if(SystemClock.elapsedRealtime()>end)throw new AssertionError("Source page not ready");SystemClock.sleep(100);}waitForIdleSync();runOnMainSync(()->chrome(a,false));View ink=image(a.getWindow().getDecorView());if(ink==null)throw new AssertionError("Page image missing");
  runOnMainSync(()->ink.performClick());waitForIdleSync();SystemClock.sleep(500);runOnMainSync(()->chrome(a,true));
  runOnMainSync(()->ink.performClick());waitForIdleSync();SystemClock.sleep(500);runOnMainSync(()->chrome(a,false));
  getUiAutomation().adoptShellPermissionIdentity("android.permission.REORDER_TASKS");try{runOnMainSync(()->a.getSystemService(ActivityManager.class).moveTaskToFront(a.getTaskId(),0));}finally{getUiAutomation().dropShellPermissionIdentity();}long focus=SystemClock.elapsedRealtime()+30000;while(!a.hasWindowFocus()&&SystemClock.elapsedRealtime()<focus)SystemClock.sleep(100);if(!a.hasWindowFocus())throw new AssertionError("Reader not focused");
  Bitmap shot=NativeScreens.capture(this,a);File dir=a.getExternalFilesDir("tests");dir.mkdirs();try(FileOutputStream out=new FileOutputStream(new File(dir,"fullscreen-warsh-night.png"))){shot.compress(Bitmap.CompressFormat.PNG,100,out);}shot.recycle();
  for(boolean show:new boolean[]{true,false}){int[] xy=new int[2];runOnMainSync(()->ink.getLocationOnScreen(xy));float x=xy[0]+ink.getWidth()/2f,y=xy[1]+ink.getHeight()/2f;long t=SystemClock.uptimeMillis();MotionEvent down=MotionEvent.obtain(t,t,0,x,y,0);down.setSource(InputDevice.SOURCE_TOUCHSCREEN);if(!getUiAutomation().injectInputEvent(down,true))throw new AssertionError("Reader touch rejected");down.recycle();SystemClock.sleep(60);MotionEvent up=MotionEvent.obtain(t,SystemClock.uptimeMillis(),1,x,y,0);up.setSource(InputDevice.SOURCE_TOUCHSCREEN);if(!getUiAutomation().injectInputEvent(up,true))throw new AssertionError("Reader touch rejected");up.recycle();waitForIdleSync();SystemClock.sleep(500);runOnMainSync(()->chrome(a,show));}
  runOnMainSync(()->a.goToPage(301));waitForIdleSync();runOnMainSync(()->chrome(a,false));runOnMainSync(a::finish);
  result.putString("result","PASS reader opens full screen; real finger taps show status/navigation bars and toolbar, second click hides them; page navigation keeps full screen");finish(Activity.RESULT_OK,result);
 }catch(Throwable e){result.putString("error",android.util.Log.getStackTraceString(e));finish(Activity.RESULT_CANCELED,result);}}
}
